<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/src/helpers.php'; $user=require_admin(); $mrId=(int)($_GET['mr_id']??0);$date=$_GET['date']??'';$where=[];$params=[];
if($mrId){$where[]='v.mr_id=?';$params[]=$mrId;} if($date!==''){ $where[]='DATE(v.visited_at)=?';$params[]=$date; }
$sql='SELECT v.*,p.name AS party_name,u.name AS mr_name FROM visits v JOIN parties p ON p.id=v.party_id JOIN users u ON u.id=v.mr_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY v.visited_at DESC';$stmt=db()->prepare($sql);$stmt->execute($params);$visits=$stmt->fetchAll();$mrs=db()->query("SELECT id,name FROM users WHERE role='employee' ORDER BY name")->fetchAll();page_start('Visits',$user);
?>
<p><a href="export.php?type=visits">Export visits CSV</a> · <a href="export.php?type=orders">Export orders CSV</a></p><form method="get" class="card"><label>MR<select name="mr_id"><option value="">All MRs</option><?php foreach($mrs as $mr): ?><option value="<?= $mr['id'] ?>" <?= $mrId===$mr['id']?'selected':'' ?>><?= e($mr['name']) ?></option><?php endforeach;?></select></label><label>Date<input name="date" type="date" value="<?= e($date) ?>"></label><button>Filter</button></form>
<?php foreach($visits as $visit): ?><article class="card small"><strong><?= e($visit['party_name']) ?></strong> · <?= e($visit['mr_name']) ?><br><?= e(date('d M Y, g:i a',strtotime($visit['visited_at']))) ?> · <span class="badge <?= $visit['status']==='converted'?'green':'grey' ?>"><?= e(str_replace('_',' ',$visit['status'])) ?></span> <span class="badge <?= $visit['location_tag']==='far'?'red':($visit['location_tag']==='near'?'blue':'orange') ?>"><?= e($visit['location_tag']) ?></span><p><?= e($visit['remark']) ?></p><?php if($visit['photo_path'] && strtotime($visit['photo_expires_at']) > time()): ?><a href="../photo.php?id=<?= $visit['id'] ?>">View photo</a><?php else:?><span class="muted">Photo expired</span><?php endif;?></article><?php endforeach; ?>
<?php page_end($user); ?>
